class Course { String code, title; int credits, labCredits; Course(String c, String t, int cr, int lab) { code=c; title=t; credits=cr; labCredits=lab; } Course(String c, String t, int cr) { this(c, t, cr, 0); } int totalCredits() { return credits + labCredits; } }
public class CourseDemo { public static void main(String[] args) { Course theory = new Course("21CSC201J", "Data Structures", 4); Course lab = new Course("21CSC205L", "DSA Lab", 3, 1); System.out.println(theory.code + " total credits: " + theory.totalCredits()); System.out.println(lab.code + " total credits: " + lab.totalCredits()); } }
